Register Individual.code:
// Register a new individual (e.g. from a field enrolment form).
createIndividual({
  name: $.data.fullName, // e.g. 'Amina Diallo'
  birthdate: $.data.dateOfBirth, // 'YYYY-MM-DD'
  gender: $.data.gender,
  phone: $.data.phone,
  address: $.data.village,
});

Register Household Group.code:
// Register a household as a group registrant.
createGroup({
  name: `${$.data.headOfHousehold} Household`,
  phone: $.data.phone,
  address: $.data.village,
});

Add Member To Household.code:
// Link an individual to a household group.
addToGroup(
  // 1) Group spp_id.
  $.data.groupSppId,
  // 2) Individual spp_id.
  $.data.individualSppId,
  // 3) Optional role in the group.
  'Head'
);

Update Individual.code:
// Update an individual's contact details.
updateIndividual(
  // 1) Individual spp_id.
  $.data.individualSppId,
  // 2) Fields to change.
  {
    phone: $.data.newPhone,
    address: $.data.newAddress,
  }
);

Enroll In Program.code:
// Enrol a registrant in a programme, e.g. a cash transfer.
enroll(
  // 1) Registrant spp_id (individual or group).
  $.data.sppId,
  // 2) Programme id.
  $.data.programId // e.g. 'PROG_2023_00000001'
);

Unenroll From Program.code:
// Exit a registrant from a programme.
unenroll(
  // 1) Registrant spp_id.
  $.data.sppId,
  // 2) Programme id.
  $.data.programId
);

Search Individuals.code:
// Find individuals by phone number.
searchIndividual(
  // 1) Domain: list of [field, operator, value] conditions.
  [['phone', '=', $.data.phone]],
  // 2) Options: limit, offset, order.
  { limit: 10 }
);

Get Household Members.code:
// List the members of a household group.
getGroupMembers(
  // 1) Group spp_id.
  $.data.groupSppId,
  // 2) Options: limit, offset, order.
  { limit: 50 }
);
